create table if not exists public.telegram_identities (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, telegram_user_id bigint not null unique, telegram_username text, first_name text, last_name text, language_code text, linked_at timestamptz not null default now(), updated_at timestamptz not null default now()); create index if not exists telegram_identities_user_id_idx on public.telegram_identities(user_id); alter table public.telegram_identities enable row level security; revoke all on public.telegram_identities from anon; revoke all on public.telegram_identities from authenticated; grant select, insert, update, delete on public.telegram_identities to authenticated; drop policy if exists telegram_identity_select_own on public.telegram_identities; drop policy if exists telegram_identity_insert_own on public.telegram_identities; drop policy if exists telegram_identity_update_own on public.telegram_identities; drop policy if exists telegram_identity_delete_own on public.telegram_identities; create policy telegram_identity_select_own on public.telegram_identities for select to authenticated using ((select auth.uid()) = user_id); create policy telegram_identity_insert_own on public.telegram_identities for insert to authenticated with check ((select auth.uid()) = user_id); create policy telegram_identity_update_own on public.telegram_identities for update to authenticated using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id); create policy telegram_identity_delete_own on public.telegram_identities for delete to authenticated using ((select auth.uid()) = user_id);;
